boolean function(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    if (ignoreCase) {
        return str.toLowerCase().endsWith(suffix.toLowerCase());
    } else {
        return str.endsWith(suffix);
    }
}

boolean function(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        for (int i = 0; i < suffixLen; i++) {
            if (Character.toUpperCase(str.charAt(strLen - suffixLen + i)) != Character.toUpperCase(suffix.charAt(i))) {
                return false;
            }
        }
    } else {
        if (str.regionMatches(strLen - suffixLen, suffix, 0, suffixLen)) {
            return true;
        } else {
            return false;
        }
    }
    return true;
}

